using System;using System.IO;using System.Drawing;using System.Windows.Forms;
class RouteVerify {
 [STAThread]static void Main(string[] args){var r=RouteModel.Load(args[0]);int tested=0;foreach(var p in r.speed_limits){double x=r.X(p.km_start);if(r.Limit(x)==null||r.Limit(x).speed_kmh!=p.speed_kmh)throw new Exception("Boundary "+p.km_start);if(r.Limit(x+.01).speed_kmh!=p.speed_kmh)throw new Exception("Boundary after "+p.km_start);tested++;}if(r.Limit(r.Length)==null||r.Limit(r.Length+.01)!=null||r.Limit(-1)!=null)throw new Exception("Outside route coverage");foreach(var p in r.profile){double x=r.X(p.km_start);if(r.Grade(x)==null||r.Grade(x).grade_permille!=p.grade_permille)throw new Exception("Gradient boundary "+p.km_start);tested++;}if(r.Km(r.X(r.initial_km))!=r.initial_km)throw new Exception("Coordinate inversion");
  int n=0;foreach(int width in new int[]{1200,1000}){using(var v=new DosRouteSurface{Route=r,Width=width,Height=width==1200?686:650}){float x=(float)r.X(r.initial_km);v.Live=new RouteLive{x=x,v=46,force=-370,current=430,excitation=400,position=18,connection=2,tm=5,tc=2.3f,tailTm=4.8f,tailTc=1.9f,gr=8.1f,ur=4.5f,limit=70,tick=431};for(int i=0;i<400;i++)v.Trace.Add(new RouteTrace{x=x-1600+i*4,v=30+i*.04f,force=i<200?550:-370,tc=i<200?0:2.3f});v.SaveRender(Path.Combine(args[1],"layout_"+width+".png"));n++;}}
  File.WriteAllText(Path.Combine(args[1],"validation.txt"),"Route boundary assertions passed="+tested+"; km direction=-1; km inversion OK; outside endpoints OK; layouts rendered="+n+"\n");Console.WriteLine("PASS "+tested+" route boundaries and coordinate mapping");
 }
}
